// Generated by sova from trails/topic-edit/trail.yaml
// Do not edit. Change the trail, then run `sova emit`.
import { expect, test } from '../fixtures';

/** A value that is new on every run (an email, a name), so a second run does not collide with the first. */
function makeUnique(): (base: string) => string {
  const seen = new Map<string, string>();
  return (base) => {
    const known = seen.get(base);
    if (known) return known;
    const tag = Math.random().toString(36).slice(2, 8);
    const at = base.indexOf('@');
    const value = at === -1 ? `${base}-${tag}` : `${base.slice(0, at)}+${tag}${base.slice(at)}`;
    seen.set(base, value);
    return value;
  };
}

test('Topic edit', async ({ page }) => {
  const unique = makeUnique();

  await test.step('Open the new topic form', async () => {
    await page.goto('/1-welcome/topic/new');
  });

  await test.step('Type a title', async () => {
    await page.getByRole('textbox', { name: 'Topic title', exact: true }).fill(unique('Edit me'));
  });

  await test.step('Type the content', async () => {
    await page.getByRole('textbox', { name: 'Content', exact: true }).fill('First version.');
  });

  await test.step('Press Post topic', async () => {
    await page.getByRole('button', { name: 'Post topic', exact: true }).click();
  });

  await test.step('The first version is shown [code]', async () => {
    await expect(page.getByRole('paragraph').filter({ hasText: /^First version\.$/ })).toBeVisible();
  });

  await test.step('Open the edit form', async () => {
    await page.getByRole('link', { name: 'Edit this topic', exact: true }).click();
  });

  await test.step('Replace the content', async () => {
    await page.getByRole('textbox', { name: 'Content', exact: true }).fill('Second version.');
  });

  await test.step('Press Save topic', async () => {
    await page.getByRole('button', { name: 'Save topic', exact: true }).click();
  });

  await test.step('The edited content is shown [code]', async () => {
    await expect(page.getByRole('paragraph').filter({ hasText: /^Second version\.$/ })).toBeVisible();
  });
});
